# Phase 2: rate a resolved ticket

Spec R1, R2, R3. Read: `src/portal.js` (`getMyTicket` returns null for another organisation), `src/store.js`,
`src/tickets.js` (`createTicket`).

## Files
- Modify `src/store.js` (add `rateTicket`), `src/tickets.js` (new fields), `src/portal.js` (add `rateTicket`).
- Create `test/csat.test.js`.

## Steps
- [ ] 1. Create `test/csat.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');
  const { closeResolved } = require('../src/jobs/close-resolved');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };
  const globex = { id: 9, orgId: 2 };

  function resolved(store, { owner = 41 } = {}) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
    if (owner) assignTicket(store, t.id, owner);
    resolveTicket(store, t.id, 41, { now: at(1) });
    return t;
  }

  test('a customer rates a resolved ticket of their organisation, and score and time are stored', () => {
    const store = createStore();
    const t = resolved(store);
    const out = portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
    assert.equal(out.rating, 4);
    assert.equal(out.rated_at, at(2).toISOString());
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const t = resolved(store);
    for (const bad of [0, 6, 3.5, '4', null, NaN, -1]) {
      assert.throws(() => portal.rateTicket(store, acme, t.id, bad), /whole number from 1 to 5/);
    }
    assert.equal(store.getTicket(t.id).rating, null);
  });

  test('an open, pending or closed ticket cannot be rated', () => {
    const store = createStore();
    const open = createTicket(store, { orgId: 1, customerId: 7, subject: 'A', body: 'x', now: at(0) });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 4), /only a resolved ticket/);
    store.updateTicket(open.id, { status: 'pending' });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 4), /only a resolved ticket/);
    const t = resolved(store);
    closeResolved(store, { now: at(5) });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 4), /only a resolved ticket/);
  });

  test('a second rating is refused and the first stays', () => {
    const store = createStore();
    const t = resolved(store);
    portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 2, { now: at(3) }), /already been rated/);
    const after = store.getTicket(t.id);
    assert.equal(after.rating, 4);
    assert.equal(after.rated_at, at(2).toISOString());
  });

  test('another organisation gets the same answer as for a ticket that does not exist', () => {
    const store = createStore();
    const t = resolved(store);
    assert.equal(portal.rateTicket(store, globex, t.id, 4), null);
    assert.equal(portal.rateTicket(store, globex, 9999, 4), null);
    assert.equal(store.getTicket(t.id).rating, null);
  });
  ```
  Evidence: `node --test test/csat.test.js` fails with "portal.rateTicket is not a function" in all five.
- [ ] 2. In `src/tickets.js` `createTicket`, add `rating: null, rated_at: null,` after `closed_at: null,`. Evidence:
  `node --test` (existing tests) still green; the export test compares against `store.getTicket`, so it follows.
- [ ] 3. In `src/store.js` add, after `updateTicket`:
  ```js
  // Sets the rating only if the ticket has none; false when it already has one. Postgres:
  // UPDATE tickets SET rating=$2, rated_at=$3 WHERE id=$1 AND rating IS NULL, true when one row changed.
  rateTicket(id, rating, ratedAt) {
    const t = tickets.get(id);
    if (!t) throw new Error(`no ticket ${id}`);
    if (t.rating != null) return false;
    t.rating = rating;
    t.rated_at = ratedAt;
    return true;
  },
  ```
- [ ] 4. In `src/portal.js` add and export:
  ```js
  // The customer rates a resolved ticket once. Another organisation's ticket answers null, like a missing one.
  function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
    const t = getMyTicket(store, customer, id);
    if (!t) return null;
    if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
    if (t.status !== STATUS.RESOLVED) throw new Error(`only a resolved ticket can be rated; this one is ${t.status}`);
    if (!store.rateTicket(id, score, now.toISOString())) throw new Error('this ticket has already been rated');
    return getMyTicket(store, customer, id);
  }
  ```
