  'use strict';
  // Nightly. Writes exports/csat-weekly.json: per agent, how many ratings their tickets received in the past seven
  // days and the average score. A rating counts for the ticket's current owner. Agents with no ratings are left out.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function weeklyCsat(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const since = now.getTime() - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const t of store.listTickets()) {
      if (t.rating == null || !t.owner_id) continue;
      if (new Date(t.rated_at).getTime() < since) continue;
      const acc = byAgent.get(t.owner_id) || { sum: 0, n: 0 };
      acc.sum += t.rating;
      acc.n += 1;
      byAgent.set(t.owner_id, acc);
    }
    const rows = [...byAgent].map(([agent_id, { sum, n }]) => ({ agent_id, ratings: n, average: Math.round((sum / n) * 100) / 100 }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'csat-weekly.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows };
  }

  module.exports = { weeklyCsat, WINDOW_DAYS };
  ```
